  "prompt": "prompts/physics_committee_terra_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum origin of cosmic structure transformed cosmology into a quantitatively testable science and provide a profound account of our observed universe.",
        "attribution": "Guth initiated inflation, Linde developed its viable realization, and Mukhanov supplied the decisive theory of primordial perturbations.",
        "maturity": "Its principal predictions have been extensively confronted with the cosmic microwave background and large-scale structure over decades.",
        "uncertainties": [
          "The underlying microphysics of inflation and a decisive primordial-gravitational-wave signature remain unsettled."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Ryan J. Foley"
      ],
      "assessment": {
        "nobel_worthiness": "The kilonova interpretation united gravitational waves, electromagnetic transients and nuclear physics, giving unusually direct evidence for a major cosmic origin of heavy elements.",
        "attribution": "Metzger and Kasen were central to the predictive radiative and nucleosynthetic framework, while Foley was central to establishing the observed transient.",
        "maturity": "GW170817 provided a landmark confirmation and subsequent observations have made the phenomenon a durable part of multi-messenger astronomy.",
        "uncertainties": [
          "The relative contribution of neutron-star mergers and other sources to the full r-process inventory remains uncertain.",
          "The compressed three-person attribution may omit other essential observational and merger-theory contributors."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B049",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "Precision CMB anisotropy mapping made cosmological parameters empirical quantities and strongly established the modern standard cosmological framework.",
        "attribution": "Bennett and Page led pivotal experimental work, while Spergel was central to translating the measurements into a coherent cosmological inference.",
        "maturity": "WMAP's conclusions have been tested and sharpened by independent CMB, large-scale-structure and other cosmological measurements.",
        "uncertainties": [
          "The standard model is highly successful phenomenologically but leaves the physical nature of dark matter and dark energy unresolved."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube opened high-energy neutrino astronomy, adding a fundamentally new messenger for observing the violent universe.",
        "attribution": "Halzen is a persuasive representative of the intellectual and experimental leadership behind IceCube, though such a large collaboration inevitably has broad credit.",
        "maturity": "The diffuse astrophysical flux is securely established and source associations have begun to demonstrate the field's scientific reach.",
        "uncertainties": [
          "The dominant source populations and production mechanisms are still incompletely identified.",
          "A single-name attribution cannot fully represent the collaboration."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "Shaun Cole",
        "Will J. Percival"
      ],
      "assessment": {
        "nobel_worthiness": "Baryon acoustic oscillations supplied a robust standard ruler and made the late-time expansion history accessible through large-scale structure.",
        "attribution": "Eisenstein, Cole and Percival made defining theoretical, observational and analysis contributions to establishing the method.",
        "maturity": "The ruler has been repeatedly measured by independent surveys and is now a central cosmological probe.",
        "uncertainties": [
          "Its interpretation remains tied to a cosmological model and does not by itself reveal the origin of cosmic acceleration."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have created an extraordinary new regime of precision measurement, with consequences from relativity tests to timekeeping.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept and Ye made decisive experimental advances and demonstrations.",
        "maturity": "Independent laboratories now achieve and use the stated precision, with a clear path toward practical metrology.",
        "uncertainties": [
          "The ultimate transformative applications, including a redefinition of the second, remain a matter of timing and institutional choice."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided one of the cleanest demonstrations that coherent quantum control can implement computation and simulation.",
        "attribution": "Cirac and Zoller gave foundational architectures and protocols, while Blatt supplied landmark experimental realization.",
        "maturity": "The platform has developed over decades into a highly controllable quantum-information technology.",
        "uncertainties": [
          "Whether scalable fault-tolerant quantum advantage will be realized remains unresolved.",
          "The broader field has many foundational contributors beyond this attribution."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Alexander Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is one of the most powerful conceptual advances in modern theoretical physics, reshaping work on quantum gravity, field theory and strongly coupled matter.",
        "attribution": "Maldacena formulated the correspondence, with Witten and Polyakov providing essential conceptual and theoretical foundations.",
        "maturity": "Its mathematical and cross-disciplinary influence is enormous and has persisted for nearly three decades.",
        "uncertainties": [
          "There is no direct empirical confirmation that the correspondence describes our universe.",
          "Its exact scope and the appropriate division of credit among antecedent contributors remain debated."
        ]
      }
    }
  ]
}
